(window.__ixData=window.__ixData||[]).push(function(D){D["geo-foundations"]=[{t:"sr",ti:"Worked Example: Write a Converse Statement",ti_ar:"مثال محلول: كتابة العكس الشرطي",steps:['A conditional statement has the form "If P, then Q." Here take: "If a shape is a square, then it has four right angles." \\(P\\)="is a square", \\(Q\\)="has four right angles."','The converse swaps P and Q: "If Q, then P."','Converse: "If a shape has four right angles, then it is a square."',"Notice this converse is actually <em>false</em> (a rectangle has four right angles but isn't always a square) — a reminder that a converse isn't automatically true just because the original statement is."],steps_ar:['العبارة الشرطية تكون على الصورة "إذا كان P، فإن Q". على سبيل المثال: "إذا كان الشكل مربعاً، فإن له أربع زوايا قائمة". هنا الفرض \\(P\\)="الشكل مربع"، والنتيجة \\(Q\\)="له أربع زوايا قائمة".','عكس العبارة الشرطية يبدل بين الفرض والنتيجة: "إذا كان Q، فإن P".','العكس هو: "إذا كان للشكل أربع زوايا قائمة، فإنه مربع".',"لاحظ أن هذا العكس <em>خاطئ</em> (فالمستطيل له أربع زوايا قائمة ولكنه ليس بالضرورة مربعاً) — وهذا تذكير بأن عكس العبارة الشرطية ليس بالضرورة صائباً لمجرد أن العبارة الأصلية صائبة."]},{t:"qc",ti:"Quick Check: Geometric Reasoning",ti_ar:"فحص سريع: التبرير الهندسي",q:"What do we call a statement accepted as true without proof?",q_ar:"ماذا نُسمي العبارة الرياضية التي تُقبل على أنها صحيحة دون برهان؟",o:["Postulate","Theorem","Corollary","Converse"],o_ar:["مسلّمة (بديهية)","نظرية","نتيجة (مبرهنة)","عكس العبارة"],a:0,ex:"A postulate (or axiom) is assumed true as a starting point; a theorem must be proved from postulates.",ex_ar:"المسلّمة أو البديهية تُفترض صحيحة كنقطة انطلاق؛ بينما النظرية يجب إثباتها بناءً على المسلمات."},{t:"num",ti:"Find Complementary Angle",ti_ar:"إيجاد قياس الزاوية المتممة",q:"Two angles are complementary. If one angle measures \\(38^{\\circ}\\), what is the measure of the other angle in degrees?",q_ar:"زاويتان متتامتان. إذا كان قياس إحداهما \\(38^{\\circ}\\)، فما قياس الزاوية الأخرى بالدرجات؟",a:52,tol:.001,h:"Complementary angles sum to 90 degrees.",h_ar:"مجموع قياسي الزاويتين المتتامتين يساوي 90 درجة.",sol:"90 - 38 = 52 degrees.",sol_ar:"90 - 38 = 52 درجة."},{t:"ord",ti:"Order the Steps: Linear Pair Algebraic Solution",ti_ar:"رتّب الخطوات: حل الزاويتين المتجاورتين على مستقيم جبرياً",q:"Arrange the steps to find angle measures for a linear pair with angles (4x + 12)° and (2x + 18)°:",q_ar:"رتب خطوات إيجاد قياس الزاويتين المتجاورتين على مستقيم (4x + 12)° و (2x + 18)°:",items:["Set the sum of the linear pair to 180°: (4x + 12) + (2x + 18) = 180","Combine like terms: 6x + 30 = 180","Subtract 30 from both sides: 6x = 150","Divide by 6 to solve for x: x = 25","Substitute x = 25 back to find the smaller angle: 2(25) + 18 = 68°"],items_ar:["مساواة مجموع الزاويتين المتكاملتين بـ 180°: (4x + 12) + (2x + 18) = 180","تجميع الحدود المتشابهة: 6x + 30 = 180","طرح 30 من كلا الطرفين: 6x = 150","القسمة على 6 لإيجاد قيمة x: x = 25","التعويض بـ x = 25 لإيجاد قياس الزاوية الصغرى: 2(25) + 18 = 68°"],sol:"Linear pairs are supplementary (sum to 180°). Solving for x allows evaluating both individual angles.",sol_ar:"الزاويتان المتجاورتان على خط مستقيم متكاملتان (مجموعهما 180°)، وإيجاد قيمة x يمكننا من حساب قياس كل منهما."},{t:"cat",ti:"Classify Angle Pairs: Complementary vs. Supplementary",ti_ar:"تصنيف أزواج الزوايا: متتامة مقابل متكاملة",categories:["Complementary (Sum = 90°)","Supplementary (Sum = 180°)"],categories_ar:["زاويتان متتامتان (مجموعهما = 90°)","زاويتان متكاملتان (مجموعهما = 180°)"],items:[{s:"35° and 55°",s_ar:"35° و 55°",cat:0},{s:"42° and 48°",s_ar:"42° و 48°",cat:0},{s:"110° and 70°",s_ar:"110° و 70°",cat:1},{s:"135° and 45°",s_ar:"135° و 45°",cat:1},{s:"Linear pair of adjacent angles on a line",s_ar:"زاويتان متجاورتان على خط مستقيم",cat:1}],sol:"Angles summing to 90° are complementary; angles summing to 180° are supplementary.",sol_ar:"الزاويتان اللتان مجموعهما 90° متتامتان؛ واللتان مجموعهما 180° متكاملتان."},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Foundations &amp; Reasoning)",q:"A student solves the equation \\(\\sqrt{2x + 25} = x - 5\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 25 = (x - 5)^2\\).","Expand the right-hand side: \\(2x + 25 = x^2 - 10x + 25\\).","Rearrange and factor: \\(x^2 - 12x = 0 \\implies x(x - 12) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 12\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{25} = -5\\) (\\(5 = -5\\)), which is false because the principal square root is non-negative (\\(x - 5 \\ge 0\\) requires \\(x \\ge 5\\)).","Expanding \\((x - 5)^2\\) should give \\(x^2 - 25\\) with no middle term.","Factoring \\(x^2 - 12x = 0\\) only yields \\(x = 12\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 25} = x - 5\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 5 \\ge 0 \\iff x \\ge 5\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 12\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Foundations &amp; Reasoning)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 25} = x - 5\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 25 = (x - 5)^2\\).","فك المربع الكامل: \\(2x + 25 = x^2 - 10x + 25\\).","الترتيب والتحليل: \\(x^2 - 12x = 0 \\implies x(x - 12) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 12\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(5 = -5\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 5\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 5 \\ge 0 \\implies x \\ge 5\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 12\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Foundations &amp; Reasoning)",q:"Let \\(f(x) = x^2 - 10x + 27\\) for \\(x \\ge 5\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 5)^2 - 25 + 27 = (x - 5)^2 + 2\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge 2\\) (or \\([2, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 5)^2 + 2 \\implies (x - 5)^2 = y - 2\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 5\\)): \\(f^{-1}(x) = 5 + \\sqrt{x - 2}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge 2\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - 2}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 5\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Foundations &amp; Reasoning)",q_ar:"لتكن \\(f(x) = x^2 - 10x + 27\\) حيث \\(x \\ge 5\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(5 + \\sqrt{x - 2}\\) لأن \\(x \\ge 5\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Foundations &amp; Reasoning)",steps:[{l:"In \\(y = x^2 - 10x + 27\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"5",h:"Take half of 10."},{l:"Compute the minimum value \\(k = 27 - 5^2 =\\)",a:"2",h:"Subtract 25 from 27."},{l:"Evaluate \\(y\\) when \\(x = 7\\): \\(y =\\)",a:"6",h:"Compute \\((2)^2 + 2\\)."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Foundations &amp; Reasoning)",steps_ar:[{l:"في الدالة \\(y = x^2 - 10x + 27\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"5",h:"اقسم معامل x وهو 10 على 2."},{l:"احسب القيمة الصغرى \\(k = 27 - 5^2 =\\)",a:"2",h:"اطرح 25 من 27."},{l:"احسب قيمة \\(y\\) عندما \\(x = 7\\):",a:"6",h:"احسب \\(4 + 2\\)."}]},{t:"mt",ti:"Matching: Core Algebraic & Analytic Principles (Foundations &amp; Reasoning)",p:[{l:"\\(b^2 - 4ac = 0\\)",r:"Line is tangent to the quadratic curve (1 repeated root)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"Equals \\(\\text{ran}(f)\\) (Range of original function)"},{l:"\\(f(x - h) + k\\)",r:"Translation by vector \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"Vieta's root-coefficient relations"}],ti_ar:"مطابقة: المبادئ الجبرية والتحليلية الأساسية (Foundations &amp; Reasoning)",p_ar:[{l:"\\(b^2 - 4ac = 0\\)",r:"المستقيم مماس للمنحنى التربيعي (جذر حقيقي مكرر)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"يساوي مدى الدالة الأصلية \\(\\text{ran}(f)\\)"},{l:"\\(f(x - h) + k\\)",r:"إزاحة هندسية بالمتجه \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"علاقات فييت بين الجذور والمعاملات"}]}];D["geo-lines"]=[{t:"qc",ti:"Quick Check: Parallel Lines",ti_ar:"فحص سريع: المستقيمات المتوازية",q:"Co-interior angles between parallel lines sum to:",q_ar:"مجموع الزاويتين الداخليتين المتحالفتين بين مستقيمين متوازيين يساوي:",o:["90°","180°","270°","360°"],o_ar:["90°","180°","270°","360°"],a:1,ex:"Supplementary angles — sum to \\(180°\\).",ex_ar:"زاويتان متكاملتان — مجموعهما \\(180°\\)."},{t:"mt",ti:"Matching: Angle Relationships",ti_ar:"مطابقة: علاقات الزوايا الناتجة عن قاطع",p:[{l:"Alternate interior angles",l_ar:"زاويتان متبادلتان داخلياً",r:"Equal: the Z shape",r_ar:"متطابقتان: على شكل حرف Z"},{l:"Corresponding angles",l_ar:"زاويتان متناظرتان",r:"Equal: the F shape",r_ar:"متطابقتان: على شكل حرف F"},{l:"Co-interior (consecutive)",l_ar:"زاويتان متحالفتان (داخليتان)",r:"Supplementary, sum 180°: the C shape",r_ar:"متكاملتان مجموعهما 180°: على شكل حرف C"},{l:"Vertical angles",l_ar:"زاويتان متقابلتان بالرأس",r:"Equal: opposite each other at an X",r_ar:"متطابقتان: متقابلتان عند تقاطع X"}]},{t:"ord",ti:"Order the Steps: Solve for Transversal Angle",ti_ar:"رتّب الخطوات: إيجاد زاوية القاطع",q:"Order the steps to find angle \\(x\\) when two parallel lines cut by a transversal have consecutive interior angles \\(2x + 10\\) and \\(3x + 20\\):",q_ar:"رتب خطوات إيجاد قيمة \\(x\\) لمستقيمين متوازيين يقطعهما قاطع وزاويتاهما الداخليتان المتحالفتان هما \\(2x + 10\\) و \\(3x + 20\\):",items:["Set up equation: (2x + 10) + (3x + 20) = 180","Combine like terms: 5x + 30 = 180","Subtract 30: 5x = 150","Divide by 5: x = 30"],items_ar:["كتابة المعادلة: (2x + 10) + (3x + 20) = 180","تجميع الحدود المتشابهة: 5x + 30 = 180","طرح 30 من الطرفين: 5x = 150","القسمة على 5: x = 30"],sol:"Consecutive interior angles are supplementary, so their sum is 180°.",sol_ar:"الزاويتان الداخليتان المتحالفتان متكاملتان، لذا مجموعهما يساوي 180°."},{t:"num",ti:"Calculate Alternate Interior Angle",ti_ar:"حساب الزاوية المتبادلة داخلياً",q:"Two parallel lines are cut by a transversal. If one alternate interior angle measures \\(114^{\\circ}\\), what is the measure of the consecutive interior angle on the same side of the transversal in degrees?",q_ar:"قطع قاطع مستقيمين متوازيين. إذا كان قياس إحدى الزوايا المتبادلة داخلياً \\(114^{\\circ}\\)، فما قياس الزاوية المتحالفة معها في نفس جهة القاطع بالدرجات؟",a:66,tol:.001,h:"Consecutive interior angles are supplementary to the alternate interior angle.",h_ar:"الزوايا المتحالفة تكون متكاملة مع الزاوية المتبادلة داخلياً.",sol:"Consecutive interior angle = 180 - 114 = 66 degrees.",sol_ar:"قياس الزاوية المتحالفة = 180 - 114 = 66 درجة."},{t:"cat",ti:"Classify Transversal Angle Relationships",ti_ar:"تصنيف علاقات زوايا القاطع",categories:["Congruent Angles (Equal Measure)","Supplementary Angles (Sum = 180°)"],categories_ar:["زوايا متطابقة (متساوية في القياس)","زوايا متكاملة (مجموعها = 180°)"],items:[{s:"Alternate interior angles",s_ar:"الزاويتان المتبادلتان داخلياً",cat:0},{s:"Corresponding angles",s_ar:"الزاويتان المتناظرتان",cat:0},{s:"Alternate exterior angles",s_ar:"الزاويتان المتبادلتان خارجياً",cat:0},{s:"Consecutive interior angles (co-interior)",s_ar:"الزاويتان الداخليتان المتحالفتان",cat:1},{s:"Consecutive exterior angles",s_ar:"الزاويتان الخارجيتان في جهة واحدة من القاطع",cat:1}],sol:"When parallel lines are cut by a transversal, alternate and corresponding pairs are equal; consecutive pairs are supplementary.",sol_ar:"عند قطع مستقيمين متوازيين بقاطع، تكون الزوايا المتبادلة والمتناظرة متطابقة، بينما تكون الزوايا المتحالفة متكاملة."},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Lines &amp; Angles)",q:"A student solves the equation \\(\\sqrt{2x + 9} = x - 3\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 9 = (x - 3)^2\\).","Expand the right-hand side: \\(2x + 9 = x^2 - 6x + 9\\).","Rearrange and factor: \\(x^2 - 8x = 0 \\implies x(x - 8) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 8\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{9} = -3\\) (\\(3 = -3\\)), which is false because the principal square root is non-negative (\\(x - 3 \\ge 0\\) requires \\(x \\ge 3\\)).","Expanding \\((x - 3)^2\\) should give \\(x^2 - 9\\) with no middle term.","Factoring \\(x^2 - 8x = 0\\) only yields \\(x = 8\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 9} = x - 3\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 3 \\ge 0 \\iff x \\ge 3\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 8\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Lines &amp; Angles)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 9} = x - 3\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 9 = (x - 3)^2\\).","فك المربع الكامل: \\(2x + 9 = x^2 - 6x + 9\\).","الترتيب والتحليل: \\(x^2 - 8x = 0 \\implies x(x - 8) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 8\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(3 = -3\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 3\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 3 \\ge 0 \\implies x \\ge 3\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 8\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Lines &amp; Angles)",q:"Let \\(f(x) = x^2 - 6x + 11\\) for \\(x \\ge 3\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 3)^2 - 9 + 11 = (x - 3)^2 + 2\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge 2\\) (or \\([2, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 3)^2 + 2 \\implies (x - 3)^2 = y - 2\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 3\\)): \\(f^{-1}(x) = 3 + \\sqrt{x - 2}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge 2\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - 2}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 3\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Lines &amp; Angles)",q_ar:"لتكن \\(f(x) = x^2 - 6x + 11\\) حيث \\(x \\ge 3\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(3 + \\sqrt{x - 2}\\) لأن \\(x \\ge 3\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Lines &amp; Angles)",steps:[{l:"In \\(y = x^2 - 6x + 11\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"3",h:"Take half of 6."},{l:"Compute the minimum value \\(k = 11 - 3^2 =\\)",a:"2",h:"Subtract 9 from 11."},{l:"Evaluate \\(y\\) when \\(x = 5\\): \\(y =\\)",a:"6",h:"Compute \\((2)^2 + 2\\)."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Lines &amp; Angles)",steps_ar:[{l:"في الدالة \\(y = x^2 - 6x + 11\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"3",h:"اقسم معامل x وهو 6 على 2."},{l:"احسب القيمة الصغرى \\(k = 11 - 3^2 =\\)",a:"2",h:"اطرح 9 من 11."},{l:"احسب قيمة \\(y\\) عندما \\(x = 5\\):",a:"6",h:"احسب \\(4 + 2\\)."}]}];D["geo-triangles"]=[{t:"mt",ti:"Matching: Triangle Congruence",ti_ar:"مطابقة: حالات تطابق المثلثات",p:[{l:"Side-Side-Side",l_ar:"ضلع-ضلع-ضلع",r:"SSS",r_ar:"SSS"},{l:"Side-Angle-Side",l_ar:"ضلع-زاوية-ضلع",r:"SAS",r_ar:"SAS"},{l:"Angle-Side-Angle",l_ar:"زاوية-ضلع-زاوية",r:"ASA",r_ar:"ASA"},{l:"Angle-Angle-Side",l_ar:"زاوية-زاوية-ضلع",r:"AAS",r_ar:"AAS"}]},{t:"sr",ti:"Worked Example: Find the Missing Angle",ti_ar:"مثال محلول: إيجاد الزاوية المجهولة في مثلث",steps:["In \\(\\triangle ABC\\), \\(\\angle A=50°\\) and \\(\\angle B=70°\\). The angles of a triangle always sum to \\(180°\\).","Set up the equation: \\(50°+70°+\\angle C=180°\\).","Solve: \\(\\angle C=180°-120°=60°\\)."],steps_ar:["في المثلث \\(\\triangle ABC\\)، قياس \\(\\angle A=50°\\) وقياس \\(\\angle B=70°\\). مجموع زوايا أي مثلث يساوي دائماً \\(180°\\).","كتابة المعادلة: \\(50°+70°+\\angle C=180°\\).","حل المعادلة: \\(\\angle C=180°-120°=60°\\)."]},{t:"num",ti:"Find Missing Triangle Angle",ti_ar:"إيجاد قياس الزاوية المجهولة في المثلث",q:"In \\(\\triangle PQR\\), \\(m\\angle P = 47^{\\circ}\\) and \\(m\\angle Q = 68^{\\circ}\\). Find the measure of \\(m\\angle R\\) in degrees:",q_ar:"في المثلث \\(\\triangle PQR\\)، قياس \\(m\\angle P = 47^{\\circ}\\) وقياس \\(m\\angle Q = 68^{\\circ}\\). أوجد قياس \\(m\\angle R\\) بالدرجات:",a:65,tol:.001,h:"The interior angles of a triangle sum to 180°.",h_ar:"مجموع الزوايا الداخلية لأي مثلث يساوي 180°.",sol:"180 - 47 - 68 = 65 degrees.",sol_ar:"180 - 47 - 68 = 65 درجة."},{t:"ord",ti:"Order the Steps: Exterior Angle Equation",ti_ar:"رتّب الخطوات: معادلة الزاوية الخارجية للمثلث",q:"Arrange the steps to find angle A in △ABC with exterior angle 134° at C and remote interior angles A = (5x - 4)° and B = (3x + 10)°:",q_ar:"رتب خطوات إيجاد الزاوية A في المثلث △ABC الذي قياس زاويته الخارجية عند الرأس C هو 134° وزاويتاه الداخلتان البعيدتان هما A = (5x - 4)° و B = (3x + 10)°:",items:["Apply Exterior Angle Theorem: (5x - 4) + (3x + 10) = 134","Combine like terms: 8x + 6 = 134","Subtract 6: 8x = 128","Divide by 8: x = 16","Substitute x = 16 into angle A: 5(16) - 4 = 76°"],items_ar:["تطبيق نظرية الزاوية الخارجية للمثلث: (5x - 4) + (3x + 10) = 134","تجميع الحدود المتشابهة: 8x + 6 = 134","طرح 6 من الطرفين: 8x = 128","القسمة على 8: x = 16","التعويض بـ x = 16 في الزاوية A: 5(16) - 4 = 76°"],sol:"The measure of an exterior angle of a triangle equals the sum of its two remote interior angles.",sol_ar:"قياس الزاوية الخارجية للمثلث يساوي مجموع قياسي الزاويتين الداخلتين البعيدتين."},{t:"cat",ti:"Classify Triangle Criteria: Valid Congruence vs. Invalid",ti_ar:"تصنيف معايير المثلثات: حالات تطابق صحيحة مقابل غير كافية",categories:["Valid Triangle Congruence Theorem","Not Sufficient for Congruence"],categories_ar:["حالة تطابق صحيحة للمثلثات","غير كافية لإثبات التطابق"],items:[{s:"Side-Side-Side (SSS)",s_ar:"ضلع-ضلع-ضلع (SSS)",cat:0},{s:"Side-Angle-Side (SAS)",s_ar:"ضلع-زاوية-ضلع (SAS)",cat:0},{s:"Angle-Side-Angle (ASA)",s_ar:"زاوية-ضلع-زاوية (ASA)",cat:0},{s:"Angle-Angle-Angle (AAA, similarity only)",s_ar:"زاوية-زاوية-زاوية (AAA، تشابه فقط)",cat:1},{s:"Side-Side-Angle (SSA, ambiguous case)",s_ar:"ضلع-ضلع-زاوية (SSA، حالة غامضة)",cat:1}],sol:"SSS, SAS, ASA, AAS, and HL prove congruence. AAA proves similarity only, and SSA is ambiguous.",sol_ar:"تثبت حالات SSS و SAS و ASA و AAS و HL التطابق؛ بينما AAA تثبت التشابه فقط، وحالة SSA غامضة وغير كافية للتطابق."},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Triangles &amp; Congruence)",q:"A student solves the equation \\(\\sqrt{2x + 25} = x - 5\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 25 = (x - 5)^2\\).","Expand the right-hand side: \\(2x + 25 = x^2 - 10x + 25\\).","Rearrange and factor: \\(x^2 - 12x = 0 \\implies x(x - 12) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 12\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{25} = -5\\) (\\(5 = -5\\)), which is false because the principal square root is non-negative (\\(x - 5 \\ge 0\\) requires \\(x \\ge 5\\)).","Expanding \\((x - 5)^2\\) should give \\(x^2 - 25\\) with no middle term.","Factoring \\(x^2 - 12x = 0\\) only yields \\(x = 12\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 25} = x - 5\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 5 \\ge 0 \\iff x \\ge 5\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 12\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Triangles &amp; Congruence)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 25} = x - 5\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 25 = (x - 5)^2\\).","فك المربع الكامل: \\(2x + 25 = x^2 - 10x + 25\\).","الترتيب والتحليل: \\(x^2 - 12x = 0 \\implies x(x - 12) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 12\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(5 = -5\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 5\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 5 \\ge 0 \\implies x \\ge 5\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 12\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Triangles &amp; Congruence)",q:"Let \\(f(x) = x^2 - 10x + 26\\) for \\(x \\ge 5\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 5)^2 - 25 + 26 = (x - 5)^2 + 1\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge 1\\) (or \\([1, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 5)^2 + 1 \\implies (x - 5)^2 = y - 1\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 5\\)): \\(f^{-1}(x) = 5 + \\sqrt{x - 1}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge 1\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - 1}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 5\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Triangles &amp; Congruence)",q_ar:"لتكن \\(f(x) = x^2 - 10x + 26\\) حيث \\(x \\ge 5\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(5 + \\sqrt{x - 1}\\) لأن \\(x \\ge 5\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Triangles &amp; Congruence)",steps:[{l:"In \\(y = x^2 - 10x + 26\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"5",h:"Take half of 10."},{l:"Compute the minimum value \\(k = 26 - 5^2 =\\)",a:"1",h:"Subtract 25 from 26."},{l:"Evaluate \\(y\\) when \\(x = 7\\): \\(y =\\)",a:"5",h:"Compute \\((2)^2 + 1\\)."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Triangles &amp; Congruence)",steps_ar:[{l:"في الدالة \\(y = x^2 - 10x + 26\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"5",h:"اقسم معامل x وهو 10 على 2."},{l:"احسب القيمة الصغرى \\(k = 26 - 5^2 =\\)",a:"1",h:"اطرح 25 من 26."},{l:"احسب قيمة \\(y\\) عندما \\(x = 7\\):",a:"5",h:"احسب \\(4 + 1\\)."}]}];D["geo-similarity"]=[{t:"sr",ti:"Worked Example: Similar Triangles — Find a Missing Side",ti_ar:"مثال محلول: المثلثات المتشابهة — إيجاد طول ضلع مجهول",steps:["Triangles \\(ABC\\) and \\(DEF\\) are similar, with \\(AB=6\\), \\(DE=9\\), \\(BC=8\\). Corresponding sides are proportional: \\(\\dfrac{AB}{DE}=\\dfrac{BC}{EF}\\).","Substitute known values: \\(\\dfrac{6}{9}=\\dfrac{8}{EF}\\).","Cross-multiply: \\(6\\cdot EF=9\\cdot8=72\\).","Solve: \\(EF=12\\)."],steps_ar:["المثلثان \\(ABC\\) و \\(DEF\\) متشابهان، حيث \\(AB=6\\) و \\(DE=9\\) و \\(BC=8\\). الأضلاع المتناظرة متناسبة: \\(\\dfrac{AB}{DE}=\\dfrac{BC}{EF}\\).","التعويض بالقيم المعلومة: \\(\\dfrac{6}{9}=\\dfrac{8}{EF}\\).","الضرب التبادلي: \\(6\\cdot EF=9\\cdot8=72\\).","حل المعادلة: \\(EF=12\\)."]},{t:"qc",ti:"Quick Check: Similar vs Congruent",ti_ar:"فحص سريع: المتشابه مقابل المتطابق",q:"If two triangles have all corresponding angles equal, they are:",q_ar:"إذا تساوت جميع الزوايا المتناظرة في مثلثين، فإنهما يكونان:",o:["Similar","Congruent","Complementary","Perpendicular"],o_ar:["متشابهين","متطابقين","متتامين","متعامدين"],a:0,ex:"Equal angles alone guarantee similarity (AA), not necessarily equal size (congruence).",ex_ar:"تساوي الزوايا يضمن التشابه (حالة AA)، لكنه لا يضمن بالضرورة تساوي الأطوال (التطابق)."},{t:"num",ti:"Similar Triangles Area Calculation",ti_ar:"حساب مساحة المثلثات المتشابهة",q:"Two similar triangles have side ratio \\(3 : 5\\). If the smaller triangle has an area of \\(36\\ \\text{cm}^2\\), what is the area of the larger triangle in \\(\\text{cm}^2\\)?",q_ar:"مثلثان متشابهان نسبة طولي ضلعيهما المتناظرين هي \\(3 : 5\\). إذا كانت مساحة المثلث الأصغر \\(36\\ \\text{cm}^2\\)، فما مساحة المثلث الأكبر بـ \\(\\text{cm}^2\\)؟",a:100,tol:.001,h:"Areas scale by the square of the linear scale factor: (5/3)^2.",h_ar:"تتناسب المساحات مع مربع معامل القياس الخطي: (5/3)²",sol:"36 * (25/9) = 100 cm².",sol_ar:"36 * (25/9) = 100 سم²."},{t:"ord",ti:"Order the Steps: Perimeter from Similar Area Ratio",ti_ar:"رتّب الخطوات: إيجاد المحيط من نسبة المساحات المتشابهة",q:"Arrange the steps to find the perimeter of △T₂ (area 80 cm²) given similar △T₁ (area 45 cm², perimeter 27 cm):",q_ar:"رتب خطوات إيجاد محيط المثلث △T₂ (مساحته 80 سم²) بمعلومية المثلث المشابه له △T₁ (مساحته 45 سم² ومحيطه 27 سم):",items:["Compute area ratio: Area(T₂) / Area(T₁) = 80 / 45 = 16 / 9","Find linear scale factor k by taking square root: k = √(16/9) = 4/3","Set up perimeter proportion: Perimeter(T₂) = k · Perimeter(T₁)","Multiply: Perimeter(T₂) = (4/3) · 27","Compute final perimeter: 36 cm"],items_ar:["حساب نسبة المساحتين: المساحة(T₂) / المساحة(T₁) = 80 / 45 = 16 / 9","إيجاد معامل القياس الخطي k بأخذ الجذر التربيعي: k = √(16/9) = 4/3","كتابة تناسب المحيطات: محيط(T₂) = k · محيط(T₁)","الضرب: محيط(T₂) = (4/3) · 27","حساب المحيط النهائي: 36 سم"],sol:"Linear dimensions scale by k, while areas scale by k².",sol_ar:"الأبعاد الخطية تتغير بالمعامل k، بينما تتغير المساحات بالمعامل k²."},{t:"cat",ti:"Classify Scaling of Geometric Measures with Scale Factor k",ti_ar:"تصنيف مقاييس الأشكال الهندسية مع معامل القياس k",categories:["Scales by Factor k (Linear)","Scales by Factor k² (Area)"],categories_ar:["يتغير بالمعامل k (أبعاد خطية)","يتغير بالمعامل k² (مساحات)"],items:[{s:"Perimeter of polygon",s_ar:"محيط المضلع",cat:0},{s:"Side length",s_ar:"طول الضلع",cat:0},{s:"Altitude / height of triangle",s_ar:"ارتفاع المثلث",cat:0},{s:"Area of triangle",s_ar:"مساحة المثلث",cat:1},{s:"Surface area of similar shape",s_ar:"المساحة السطحية للشكل المتشابه",cat:1}],sol:"Perimeters and lengths scale linearly by k; areas scale quadratically by k².",sol_ar:"المحيطات والأطوال تتغير خطياً بالمعامل k؛ بينما تتغير المساحات بالمعامل k²."},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Similarity & Proportional Reasoning)",q:"A student solves the equation \\(\\sqrt{2x + 16} = x - 4\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 16 = (x - 4)^2\\).","Expand the right-hand side: \\(2x + 16 = x^2 - 8x + 16\\).","Rearrange and factor: \\(x^2 - 10x = 0 \\implies x(x - 10) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 10\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{16} = -4\\) (\\(4 = -4\\)), which is false because the principal square root is non-negative (\\(x - 4 \\ge 0\\) requires \\(x \\ge 4\\)).","Expanding \\((x - 4)^2\\) should give \\(x^2 - 16\\) with no middle term.","Factoring \\(x^2 - 10x = 0\\) only yields \\(x = 10\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 16} = x - 4\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 4 \\ge 0 \\iff x \\ge 4\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 10\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Similarity & Proportional Reasoning)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 16} = x - 4\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 16 = (x - 4)^2\\).","فك المربع الكامل: \\(2x + 16 = x^2 - 8x + 16\\).","الترتيب والتحليل: \\(x^2 - 10x = 0 \\implies x(x - 10) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 10\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(4 = -4\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 4\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 4 \\ge 0 \\implies x \\ge 4\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 10\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Similarity & Proportional Reasoning)",q:"Let \\(f(x) = x^2 - 8x + 20\\) for \\(x \\ge 4\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 4)^2 - 16 + 20 = (x - 4)^2 + 4\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge 4\\) (or \\([4, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 4)^2 + 4 \\implies (x - 4)^2 = y - 4\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 4\\)): \\(f^{-1}(x) = 4 + \\sqrt{x - 4}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge 4\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - 4}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 4\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Similarity & Proportional Reasoning)",q_ar:"لتكن \\(f(x) = x^2 - 8x + 20\\) حيث \\(x \\ge 4\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(4 + \\sqrt{x - 4}\\) لأن \\(x \\ge 4\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Similarity & Proportional Reasoning)",steps:[{l:"In \\(y = x^2 - 8x + 20\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"4",h:"Take half of 8."},{l:"Compute the minimum value \\(k = 20 - 4^2 =\\)",a:"4",h:"Subtract 16 from 20."},{l:"Evaluate \\(y\\) when \\(x = 6\\): \\(y =\\)",a:"8",h:"Compute \\((2)^2 + 4\\)."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Similarity & Proportional Reasoning)",steps_ar:[{l:"في الدالة \\(y = x^2 - 8x + 20\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"4",h:"اقسم معامل x وهو 8 على 2."},{l:"احسب القيمة الصغرى \\(k = 20 - 4^2 =\\)",a:"4",h:"اطرح 16 من 20."},{l:"احسب قيمة \\(y\\) عندما \\(x = 6\\):",a:"8",h:"احسب \\(4 + 4\\)."}]},{t:"mt",ti:"Matching: Core Algebraic & Analytic Principles (Similarity & Proportional Reasoning)",p:[{l:"\\(b^2 - 4ac = 0\\)",r:"Line is tangent to the quadratic curve (1 repeated root)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"Equals \\(\\text{ran}(f)\\) (Range of original function)"},{l:"\\(f(x - h) + k\\)",r:"Translation by vector \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"Vieta's root-coefficient relations"}],ti_ar:"مطابقة: المبادئ الجبرية والتحليلية الأساسية (Similarity & Proportional Reasoning)",p_ar:[{l:"\\(b^2 - 4ac = 0\\)",r:"المستقيم مماس للمنحنى التربيعي (جذر حقيقي مكرر)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"يساوي مدى الدالة الأصلية \\(\\text{ran}(f)\\)"},{l:"\\(f(x - h) + k\\)",r:"إزاحة هندسية بالمتجه \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"علاقات فييت بين الجذور والمعاملات"}]}];D["geo-right"]=[{t:"sb",ti:"Step Builder: Hypotenuse of right triangle, legs \\(5\\) and \\(12\\)",ti_ar:"بناء الحل خطوة بخطوة: وتر مثلث قائم طولا ضلعيه \\(5\\) و \\(12\\)",steps:[{l:"\\(c^2=5^2+12^2=\\)",l_ar:"\\(c^2=5^2+12^2=\\)",a:"169",h:"\\(25+144=169\\)",h_ar:"\\(25+144=169\\)"},{l:"\\(c=\\sqrt{169}=\\)",l_ar:"\\(c=\\sqrt{169}=\\)",a:"13",h:"\\(\\sqrt{169}=13\\)",h_ar:"\\(\\sqrt{169}=13\\)"}]},{t:"sr",ti:"Worked Example: 30°-60°-90° Special Right Triangle",ti_ar:"مثال محلول: المثلث القائم الخاص 30°-60°-90°",steps:["In a 30°-60°-90° triangle, the sides are in the ratio \\(1 : \\sqrt{3} : 2\\).","The hypotenuse is twice the shorter leg (opposite the 30° angle).","If the shorter leg is 4, then the hypotenuse is \\(2\\times 4 = 8\\).","The longer leg (opposite 60°) is \\(4\\sqrt{3}\\)."],steps_ar:["في المثلث القائم 30°-60°-90°، تكون النسبة بين أطوال الأضلاع هي \\(1 : \\sqrt{3} : 2\\).","طول الوتر يساوي ضعف طول الضلع الأقصر (المقابل للزاوية 30°).","إذا كان الضلع الأقصر طوله 4، فإن الوتر طوله \\(2\\times 4 = 8\\).","طول الضلع الأطول (المقابل للزاوية 60°) يساوي \\(4\\sqrt{3}\\)."]},{t:"num",ti:"Special Right Triangle Leg",ti_ar:"طول ضلع المثلث القائم الخاص",q:"In a \\(30^{\\circ}\\text{–}60^{\\circ}\\text{–}90^{\\circ}\\) right triangle, the hypotenuse has length \\(16\\). What is the length of the shorter leg (opposite 30°)?",q_ar:"في المثلث القائم \\(30^{\\circ}\\text{–}60^{\\circ}\\text{–}90^{\\circ}\\)، طول الوتر هو \\(16\\). ما طول الضلع الأقصر (المقابل للزاوية 30°)؟",a:8,tol:.001,h:"In a 30-60-90 triangle, the hypotenuse is twice the shorter leg.",h_ar:"في المثلث 30-60-90، طول الوتر يساوي ضعف طول الضلع الأقصر.",sol:"16 / 2 = 8.",sol_ar:"16 / 2 = 8."},{t:"ord",ti:"Order the Steps: Equilateral Triangle Altitude and Area",ti_ar:"رتّب الخطوات: ارتفاع ومساحة المثلث متطابق الأضلاع",q:"Arrange the steps to find the altitude and area of an equilateral triangle with side length 12 cm:",q_ar:"رتب خطوات إيجاد الارتفاع والمساحة لمثلث متطابق الأضلاع طول ضلعه 12 سم:",items:["Draw the altitude, splitting the base into two segments of length 6 cm","Recognize the 30°-60°-90° right triangle with shorter leg 6 cm","Calculate altitude (longer leg opposite 60°): h = 6√3 cm","Apply area formula: Area = (1/2) · base · height = (1/2)(12)(6√3)","Compute exact area: 36√3 cm²"],items_ar:["رسم الارتفاع الذي يقسم القاعدة إلى قطعتين متساويتين طول كل منهما 6 سم","ملاحظة تشكل مثلث قائم 30°-60°-90° ضلعه الأقصر 6 سم","حساب الارتفاع (الضلع المقابل للزاوية 60°): h = 6√3 سم","تطبيق قانون المساحة: المساحة = (1/2) · القاعدة · الارتفاع = (1/2)(12)(6√3)","حساب المساحة الدقيقة: 36√3 سم²"],sol:"The altitude of an equilateral triangle bisects the base and creates two 30-60-90 triangles.",sol_ar:"ارتفاع المثلث متطابق الأضلاع ينصف قاعدته ويقسمه إلى مثلثين قائمين 30-60-90."},{t:"cat",ti:"Classify Pythagorean Triples vs. Non-Triples",ti_ar:"تصنيف ثلاثيات فيثاغورس",categories:["Valid Pythagorean Triple (Integer Right Triangle)","Not a Pythagorean Triple"],categories_ar:["ثلاثية فيثاغورس صحيحة (أعداد كلية)","ليست ثلاثية فيثاغورس"],items:[{s:"3 - 4 - 5",s_ar:"3 - 4 - 5",cat:0},{s:"5 - 12 - 13",s_ar:"5 - 12 - 13",cat:0},{s:"8 - 15 - 17",s_ar:"8 - 15 - 17",cat:0},{s:"7 - 24 - 25",s_ar:"7 - 24 - 25",cat:0},{s:"4 - 5 - 6",s_ar:"4 - 5 - 6",cat:1},{s:"6 - 8 - 12",s_ar:"6 - 8 - 12",cat:1}],sol:"Pythagorean triples satisfy a² + b² = c² with whole integers: 3-4-5, 5-12-13, 8-15-17, 7-24-25.",sol_ar:"ثلاثيات فيثاغورس تحقق المعادلة a² + b² = c² بأعداد صحيحة موجبة: 3-4-5، 5-12-13، 8-15-17، 7-24-25."},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Right Triangles &amp; Trigonometry)",q:"A student solves the equation \\(\\sqrt{2x + 9} = x - 3\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 9 = (x - 3)^2\\).","Expand the right-hand side: \\(2x + 9 = x^2 - 6x + 9\\).","Rearrange and factor: \\(x^2 - 8x = 0 \\implies x(x - 8) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 8\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{9} = -3\\) (\\(3 = -3\\)), which is false because the principal square root is non-negative (\\(x - 3 \\ge 0\\) requires \\(x \\ge 3\\)).","Expanding \\((x - 3)^2\\) should give \\(x^2 - 9\\) with no middle term.","Factoring \\(x^2 - 8x = 0\\) only yields \\(x = 8\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 9} = x - 3\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 3 \\ge 0 \\iff x \\ge 3\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 8\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Right Triangles &amp; Trigonometry)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 9} = x - 3\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 9 = (x - 3)^2\\).","فك المربع الكامل: \\(2x + 9 = x^2 - 6x + 9\\).","الترتيب والتحليل: \\(x^2 - 8x = 0 \\implies x(x - 8) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 8\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(3 = -3\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 3\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 3 \\ge 0 \\implies x \\ge 3\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 8\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Right Triangles &amp; Trigonometry)",q:"Let \\(f(x) = x^2 - 6x + 14\\) for \\(x \\ge 3\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 3)^2 - 9 + 14 = (x - 3)^2 + 5\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge 5\\) (or \\([5, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 3)^2 + 5 \\implies (x - 3)^2 = y - 5\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 3\\)): \\(f^{-1}(x) = 3 + \\sqrt{x - 5}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge 5\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - 5}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 3\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Right Triangles &amp; Trigonometry)",q_ar:"لتكن \\(f(x) = x^2 - 6x + 14\\) حيث \\(x \\ge 3\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(3 + \\sqrt{x - 5}\\) لأن \\(x \\ge 3\\)."},{t:"mt",ti:"Matching: Core Algebraic & Analytic Principles (Right Triangles &amp; Trigonometry)",p:[{l:"\\(b^2 - 4ac = 0\\)",r:"Line is tangent to the quadratic curve (1 repeated root)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"Equals \\(\\text{ran}(f)\\) (Range of original function)"},{l:"\\(f(x - h) + k\\)",r:"Translation by vector \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"Vieta's root-coefficient relations"}],ti_ar:"مطابقة: المبادئ الجبرية والتحليلية الأساسية (Right Triangles &amp; Trigonometry)",p_ar:[{l:"\\(b^2 - 4ac = 0\\)",r:"المستقيم مماس للمنحنى التربيعي (جذر حقيقي مكرر)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"يساوي مدى الدالة الأصلية \\(\\text{ran}(f)\\)"},{l:"\\(f(x - h) + k\\)",r:"إزاحة هندسية بالمتجه \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"علاقات فييت بين الجذور والمعاملات"}]}];D["geo-quads"]=[{t:"sr",ti:"Worked Example: Sum of Interior Angles of a Hexagon",ti_ar:"مثال محلول: مجموع الزوايا الداخلية للشكل السداسي",steps:["Use the formula \\((n-2)\\times180°\\), where \\(n\\) is the number of sides.","A hexagon has \\(n=6\\) sides.","Substitute: \\((6-2)\\times180°=4\\times180°=720°\\)."],steps_ar:["استخدام القانون \\((n-2)\\times180°\\)، حيث \\(n\\) هو عدد الأضلاع.","الشكل السداسي له \\(n=6\\) أضلاع.","التعويض: \\((6-2)\\times180°=4\\times180°=720°\\)."]},{t:"qc",ti:"Quick Check: Quadrilateral Types",ti_ar:"فحص سريع: أنواع الأشكال الرباعية",q:"A parallelogram with all sides equal and no right angles is a:",q_ar:"متوازي أضلاع جميع أضلاعه متطابقة ولا توجد به زوايا قائمة هو:",o:["Rhombus","Square","Rectangle","Trapezoid"],o_ar:["معين","مربع","مستطيل","شبه منحرف"],a:0,ex:"Equal sides define a rhombus; without right angles it isn't a square.",ex_ar:"تطابق جميع الأضلاع يحدد المعين؛ وبدون زوايا قائمة لا يكون مربعاً."},{t:"num",ti:"Regular Octagon Interior Angle",ti_ar:"إيجاد زاوية الثماني المنتظم الداخلية",q:"What is the measure in degrees of each interior angle of a regular octagon (8-sided polygon)?",q_ar:"ما قياس كل زاوية داخلية في الثماني المنتظم (مضلع له 8 أضلاع) بالدرجات؟",a:135,tol:.001,h:"Exterior angle is 360 / 8 = 45°. Interior angle is 180 - 45°.",h_ar:"الزاوية الخارجية = 360 / 8 = 45°. والزاوية الداخلية = 180 - 45°.",sol:"180 - 45 = 135 degrees.",sol_ar:"180 - 45 = 135 درجة."},{t:"ord",ti:"Order the Steps: Finding Number of Sides from Interior Angle",ti_ar:"رتّب الخطوات: إيجاد عدد الأضلاع من قياس الزاوية الداخلية",q:"Arrange the steps to find the number of sides of a regular polygon with interior angle 144°:",q_ar:"رتب خطوات إيجاد عدد أضلاع مضلع منتظم قياس زاويته الداخلية 144°:",items:["Find the exterior angle using the linear pair property: Exterior = 180° - 144° = 36°","Recall the theorem: The sum of exterior angles of any convex polygon is 360°","Set up the equation for regular polygon sides: n · 36° = 360°","Divide to solve for n: n = 360° / 36°","Conclude that the polygon has 10 sides (regular decagon)"],items_ar:["إيجاد قياس الزاوية الخارجية بالتكامل مع الزاوية الداخلية: الخارجية = 180° - 144° = 36°","تذكر النظرية: مجموع قياسات الزوايا الخارجية لأي مضلع محدب يساوي 360°","كتابة معادلة عدد أضلاع المضلع المنتظم: n · 36° = 360°","القسمة لحساب n: n = 360° / 36°","استنتاج أن المضلع له 10 أضلاع (عشاري منتظم)"],sol:"Finding the exterior angle first simplifies finding the number of sides n = 360° / exterior.",sol_ar:"إيجاد الزاوية الخارجية أولاً يسهل إيجاد عدد الأضلاع n = 360° / الزاوية الخارجية."},{t:"cat",ti:"Classify Quadrilaterals: Always Perpendicular Diagonals",ti_ar:"تصنيف الأشكال الرباعية: تعامد القطرين دائماً",categories:["Diagonals Always Perpendicular (⊥)","Diagonals Not Necessarily Perpendicular"],categories_ar:["القطران متعامدان دائماً (⊥)","القطران ليسا متعامدين بالضرورة"],items:[{s:"Rhombus",s_ar:"المعين",cat:0},{s:"Square",s_ar:"المربع",cat:0},{s:"Kite",s_ar:"شبه المنحرف الدالتوني (طائرة ورقية)",cat:0},{s:"Rectangle (non-square)",s_ar:"المستطيل (غير المربع)",cat:1},{s:"General Parallelogram",s_ar:"متوازي الأضلاع العام",cat:1},{s:"Isosceles Trapezoid",s_ar:"شبه المنحرف متطابق الساقين",cat:1}],sol:"Rhombuses, squares, and kites always have mutually perpendicular diagonals.",sol_ar:"أقطار المعين والمربع وشبه المنحرف الدالتوني (طائرة ورقية) تكون دائماً متعامدة."},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Polygons &amp; Quadrilaterals)",q:"A student solves the equation \\(\\sqrt{2x + 16} = x - 4\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 16 = (x - 4)^2\\).","Expand the right-hand side: \\(2x + 16 = x^2 - 8x + 16\\).","Rearrange and factor: \\(x^2 - 10x = 0 \\implies x(x - 10) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 10\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{16} = -4\\) (\\(4 = -4\\)), which is false because the principal square root is non-negative (\\(x - 4 \\ge 0\\) requires \\(x \\ge 4\\)).","Expanding \\((x - 4)^2\\) should give \\(x^2 - 16\\) with no middle term.","Factoring \\(x^2 - 10x = 0\\) only yields \\(x = 10\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 16} = x - 4\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 4 \\ge 0 \\iff x \\ge 4\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 10\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Polygons &amp; Quadrilaterals)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 16} = x - 4\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 16 = (x - 4)^2\\).","فك المربع الكامل: \\(2x + 16 = x^2 - 8x + 16\\).","الترتيب والتحليل: \\(x^2 - 10x = 0 \\implies x(x - 10) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 10\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(4 = -4\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 4\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 4 \\ge 0 \\implies x \\ge 4\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 10\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Polygons &amp; Quadrilaterals)",q:"Let \\(f(x) = x^2 - 8x + 16\\) for \\(x \\ge 4\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 4)^2 - 16 + 16 = (x - 4)^2 + 0\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge 0\\) (or \\([0, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 4)^2 + 0 \\implies (x - 4)^2 = y - 0\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 4\\)): \\(f^{-1}(x) = 4 + \\sqrt{x - 0}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge 0\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - 0}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 4\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Polygons &amp; Quadrilaterals)",q_ar:"لتكن \\(f(x) = x^2 - 8x + 16\\) حيث \\(x \\ge 4\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(4 + \\sqrt{x - 0}\\) لأن \\(x \\ge 4\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Polygons &amp; Quadrilaterals)",steps:[{l:"In \\(y = x^2 - 8x + 16\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"4",h:"Take half of 8."},{l:"Compute the minimum value \\(k = 16 - 4^2 =\\)",a:"0",h:"Subtract 16 from 16."},{l:"Evaluate \\(y\\) when \\(x = 6\\): \\(y =\\)",a:"4",h:"Compute \\((2)^2 + 0\\)."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Polygons &amp; Quadrilaterals)",steps_ar:[{l:"في الدالة \\(y = x^2 - 8x + 16\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"4",h:"اقسم معامل x وهو 8 على 2."},{l:"احسب القيمة الصغرى \\(k = 16 - 4^2 =\\)",a:"0",h:"اطرح 16 من 16."},{l:"احسب قيمة \\(y\\) عندما \\(x = 6\\):",a:"4",h:"احسب \\(4 + 0\\)."}]},{t:"mt",ti:"Matching: Core Algebraic & Analytic Principles (Polygons &amp; Quadrilaterals)",p:[{l:"\\(b^2 - 4ac = 0\\)",r:"Line is tangent to the quadratic curve (1 repeated root)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"Equals \\(\\text{ran}(f)\\) (Range of original function)"},{l:"\\(f(x - h) + k\\)",r:"Translation by vector \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"Vieta's root-coefficient relations"}],ti_ar:"مطابقة: المبادئ الجبرية والتحليلية الأساسية (Polygons &amp; Quadrilaterals)",p_ar:[{l:"\\(b^2 - 4ac = 0\\)",r:"المستقيم مماس للمنحنى التربيعي (جذر حقيقي مكرر)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"يساوي مدى الدالة الأصلية \\(\\text{ran}(f)\\)"},{l:"\\(f(x - h) + k\\)",r:"إزاحة هندسية بالمتجه \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"علاقات فييت بين الجذور والمعاملات"}]}];D["geo-circles"]=[{t:"tf",ti:"True or False: Circle Theorems",ti_ar:"صواب أم خطأ: نظريات الدائرة",items:[{s:"Inscribed angle = half the central angle on same arc",s_ar:"الزاوية المحيطية = نصف قياس الزاوية المركزية المشتركة معها في القوس",a:true,ex:"Inscribed Angle Theorem.",ex_ar:"نظرية الزاوية المحيطية."},{s:"Angle in a semicircle is 90°",s_ar:"الزاوية المحيطية المرسومة في نصف دائرة قياسها 90°",a:true,ex:"Thales' Theorem.",ex_ar:"نظرية طاليس."},{s:"Two tangents from an external point have different lengths",s_ar:"المماسان المرسومان للدائرة من نقطة خارجها لهما طولان مختلفان",a:false,ex:"Equal tangent lengths from external point.",ex_ar:"القطعتان المماستان المرسومتان من نقطة خارج دائرة متطابقتان."},{s:"Tangent is perpendicular to radius at contact point",s_ar:"المماس يكون عمودياً على نصف القطر عند نقطة التماس",a:true,ex:"Tangent-radius property.",ex_ar:"خاصية المماس ونصف القطر."}]},{t:"sr",ti:"Worked Example: Arc Length of a Sector",ti_ar:"مثال محلول: طول قوس القطاع الدائري",steps:["Find the arc length of a \\(60°\\) sector in a circle of radius \\(9\\). Arc length formula: \\(s=\\dfrac{\\theta}{360°}\\times2\\pi r\\).","Substitute \\(\\theta=60°\\), \\(r=9\\): \\(s=\\dfrac{60}{360}\\times2\\pi(9)\\).","Simplify: \\(s=\\dfrac16\\times18\\pi=3\\pi\\)."],steps_ar:["أوجد طول قوس قطاع زاويته المركزية \\(60°\\) في دائرة نصف قطرها \\(9\\). قانون طول القوس: \\(s=\\dfrac{\\theta}{360°}\\times2\\pi r\\).","التعويض بـ \\(\\theta=60°\\) و \\(r=9\\): \\(s=\\dfrac{60}{360}\\times2\\pi(9)\\).","التبسيط: \\(s=\\dfrac16\\times18\\pi=3\\pi\\)."]},{t:"num",ti:"Inscribed Angle Measure",ti_ar:"قياس الزاوية المحيطية",q:"An inscribed angle intercepts an arc of \\(74^{\\circ}\\). What is the measure of the inscribed angle in degrees?",q_ar:"زاوية محيطية يقابلها قوس قياسه \\(74^{\\circ}\\). ما قياس الزاوية المحيطية بالدرجات؟",a:37,tol:.001,h:"An inscribed angle equals half its intercepted arc.",h_ar:"قياس الزاوية المحيطية يساوي نصف قياس القوس المقابل لها.",sol:"74 / 2 = 37 degrees.",sol_ar:"74 / 2 = 37 درجة."},{t:"ord",ti:"Order the Steps: Tangent Length from External Point",ti_ar:"رتّب الخطوات: طول المماس المرسوم من نقطة خارج الدائرة",q:"Arrange the steps to find tangent length PA to a circle with radius 5 cm from external point P with PO = 13 cm:",q_ar:"رتب خطوات إيجاد طول المماس PA لدائرة نصف قطرها 5 سم من نقطة خارجها P حيث البعد عن المركز PO = 13 سم:",items:["Identify that radius OA is perpendicular to tangent PA at point of tangency A","Recognize △PAO as a right triangle with right angle at vertex A","Identify hypotenuse PO = 13 cm and leg OA = 5 cm","Apply the Pythagorean theorem: PA² + 5² = 13² ⟹ PA² = 169 - 25 = 144","Take square root to find tangent length: PA = 12 cm"],items_ar:["ملاحظة أن نصف القطر OA عمودي على المماس PA عند نقطة التماس A","استنتاج أن المثلث △PAO قائم الزاوية عند الرأس A","تحديد طول الوتر PO = 13 سم وطول الساق OA = 5 سم","تطبيق نظرية فيثاغورس: PA² + 5² = 13² ⟹ PA² = 169 - 25 = 144","أخذ الجذر التربيعي لإيجاد طول المماس: PA = 12 سم"],sol:"Tangent segments from an external point form right triangles with the radius at the point of contact.",sol_ar:"المماس ونصف القطر يشكلان مثلثاً قائماً عند نقطة التماس."},{t:"cat",ti:"Classify Angles in Circles by Vertex Location",ti_ar:"تصنيف زوايا الدائرة حسب موقع الرأس",categories:["Vertex on Circle (Inscribed / Tangent-Chord)","Vertex at Center (Central Angle)"],categories_ar:["الرأس على الدائرة (محيطية / مماسية)","الرأس في المركز (زاوية مركزية)"],items:[{s:"Angle intercepting arc with measure equal to arc (m∠ = θ)",s_ar:"زاوية قياسها يساوي قياس القوس المقابل تماماً (m∠ = θ)",cat:1},{s:"Angle intercepting arc with measure equal to half arc (m∠ = θ / 2)",s_ar:"زاوية قياسها يساوي نصف قياس القوس المقابل (m∠ = θ / 2)",cat:0},{s:"Angle inscribed in a semicircle (always 90°)",s_ar:"زاوية محيطية مرسومة في نصف دائرة (قياسها 90° دائماً)",cat:0},{s:"Central angle formed by two radii",s_ar:"زاوية مركزية تتكون من نصفي قطرين",cat:1}],sol:"Central angles equal their intercepted arc; inscribed angles and tangent-chord angles equal half their intercepted arc.",sol_ar:"الزوايا المركزية تساوي قياس القوس المقابل لها؛ بينما الزوايا المحيطية والمماسية تساوي نصف قياس القوس المقابل."},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Circles)",q:"A student solves the equation \\(\\sqrt{2x + 25} = x - 5\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 25 = (x - 5)^2\\).","Expand the right-hand side: \\(2x + 25 = x^2 - 10x + 25\\).","Rearrange and factor: \\(x^2 - 12x = 0 \\implies x(x - 12) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 12\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{25} = -5\\) (\\(5 = -5\\)), which is false because the principal square root is non-negative (\\(x - 5 \\ge 0\\) requires \\(x \\ge 5\\)).","Expanding \\((x - 5)^2\\) should give \\(x^2 - 25\\) with no middle term.","Factoring \\(x^2 - 12x = 0\\) only yields \\(x = 12\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 25} = x - 5\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 5 \\ge 0 \\iff x \\ge 5\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 12\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Circles)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 25} = x - 5\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 25 = (x - 5)^2\\).","فك المربع الكامل: \\(2x + 25 = x^2 - 10x + 25\\).","الترتيب والتحليل: \\(x^2 - 12x = 0 \\implies x(x - 12) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 12\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(5 = -5\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 5\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 5 \\ge 0 \\implies x \\ge 5\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 12\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Circles)",q:"Let \\(f(x) = x^2 - 10x + 32\\) for \\(x \\ge 5\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 5)^2 - 25 + 32 = (x - 5)^2 + 7\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge 7\\) (or \\([7, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 5)^2 + 7 \\implies (x - 5)^2 = y - 7\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 5\\)): \\(f^{-1}(x) = 5 + \\sqrt{x - 7}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge 7\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - 7}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 5\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Circles)",q_ar:"لتكن \\(f(x) = x^2 - 10x + 32\\) حيث \\(x \\ge 5\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(5 + \\sqrt{x - 7}\\) لأن \\(x \\ge 5\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Circles)",steps:[{l:"In \\(y = x^2 - 10x + 32\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"5",h:"Take half of 10."},{l:"Compute the minimum value \\(k = 32 - 5^2 =\\)",a:"7",h:"Subtract 25 from 32."},{l:"Evaluate \\(y\\) when \\(x = 7\\): \\(y =\\)",a:"11",h:"Compute \\((2)^2 + 7\\)."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Circles)",steps_ar:[{l:"في الدالة \\(y = x^2 - 10x + 32\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"5",h:"اقسم معامل x وهو 10 على 2."},{l:"احسب القيمة الصغرى \\(k = 32 - 5^2 =\\)",a:"7",h:"اطرح 25 من 32."},{l:"احسب قيمة \\(y\\) عندما \\(x = 7\\):",a:"11",h:"احسب \\(4 + 7\\)."}]},{t:"mt",ti:"Matching: Core Algebraic & Analytic Principles (Circles)",p:[{l:"\\(b^2 - 4ac = 0\\)",r:"Line is tangent to the quadratic curve (1 repeated root)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"Equals \\(\\text{ran}(f)\\) (Range of original function)"},{l:"\\(f(x - h) + k\\)",r:"Translation by vector \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"Vieta's root-coefficient relations"}],ti_ar:"مطابقة: المبادئ الجبرية والتحليلية الأساسية (Circles)",p_ar:[{l:"\\(b^2 - 4ac = 0\\)",r:"المستقيم مماس للمنحنى التربيعي (جذر حقيقي مكرر)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"يساوي مدى الدالة الأصلية \\(\\text{ran}(f)\\)"},{l:"\\(f(x - h) + k\\)",r:"إزاحة هندسية بالمتجه \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"علاقات فييت بين الجذور والمعاملات"}]}];D["geo-solids"]=[{t:"sr",ti:"Worked Example: Volume of a Cylinder",ti_ar:"مثال محلول: حجم الأسطوانة",steps:["Find the volume of a cylinder with radius \\(4\\) and height \\(10\\). Volume formula: \\(V=\\pi r^2h\\).","Substitute \\(r=4\\), \\(h=10\\): \\(V=\\pi(4)^2(10)\\).","Compute: \\(V=160\\pi\\)."],steps_ar:["أوجد حجم أسطوانة نصف قطر قاعدتها \\(4\\) وارتفاعها \\(10\\). قانون الحجم: \\(V=\\pi r^2h\\).","التعويض بـ \\(r=4\\) و \\(h=10\\): \\(V=\\pi(4)^2(10)\\).","الحساب: \\(V=160\\pi\\)."]},{t:"qc",ti:"Quick Check: Surface Area",ti_ar:"فحص سريع: المساحة الكلية لسطح المكعب",q:"Surface area of a cube with side length 5:",q_ar:"المساحة الكلية لسطح مكعب طول ضلعه 5 تساوي:",o:["150","125","100","25"],o_ar:["150","125","100","25"],a:0,ex:"\\(SA=6s^2=6(5^2)=6(25)=150\\).",ex_ar:"\\(SA=6s^2=6(5^2)=6(25)=150\\)."},{t:"num",ti:"Cone Volume Factor",ti_ar:"علاقة حجم المخروط بالأسطوانة",q:"A cylinder has a volume of \\(75\\pi\\ \\text{cm}^3\\). A cone has the exact same radius and height as the cylinder. What is the volume of the cone in \\(\\text{cm}^3\\) divided by \\(\\pi\\)?",q_ar:"أسطوانة حجمها \\(75\\pi\\ \\text{cm}^3\\). ومخروط له نفس نصف القطر والارتفاع تماماً كالأسطوانة. ما حجم المخروط بـ \\(\\text{cm}^3\\) مقسوماً على \\(\\pi\\)؟",a:25,tol:.001,h:"A cone volume is 1/3 of the cylinder with identical dimensions.",h_ar:"حجم المخروط يساوي ثلث (1/3) حجم الأسطوانة المشتركة معه في القاعدة والارتفاع.",sol:"75 / 3 = 25.",sol_ar:"75 / 3 = 25."},{t:"ord",ti:"Order the Steps: Recasting a Sphere into a Cylinder",ti_ar:"رتّب الخطوات: صهر وإعادة تشكيل كرة إلى أسطوانة",q:"Arrange the steps to find the height of a cylinder (radius 2 cm) recast from a solid sphere (radius 3 cm):",q_ar:"رتب خطوات إيجاد ارتفاع أسطوانة (نصف قطرها 2 سم) أعيد تشكيلها من كرة مصمتة (نصف قطرها 3 سم):",items:["Compute sphere volume: V = (4/3)π r³ = (4/3)π (27) = 36π cm³","Set up cylinder volume formula: V = π R² h = π (2²) h = 4π h","Equate volumes: 4π h = 36π","Divide both sides by 4π: h = 36π / 4π","State final cylinder height: 9 cm"],items_ar:["حساب حجم الكرة: V = (4/3)π r³ = (4/3)π (27) = 36π سم³","كتابة قانون حجم الأسطوانة: V = π R² h = π (2²) h = 4π h","مساواة الحجمين (ثبوت الحجم): 4π h = 36π","قسمة الطرفين على 4π: h = 36π / 4π","تحديد الارتفاع النهائي للأسطوانة: 9 سم"],sol:"Conservation of volume means equating the sphere volume with the cylinder volume formula.",sol_ar:"مبدأ حفظ الحجم يعني مساواة حجم الكرة الأصلي بقانون حجم الأسطوانة الجديد."},{t:"cat",ti:"Classify Solids by Volume Formula Type",ti_ar:"تصنيف المجسمات حسب نوع قانون الحجم",categories:["Base Times Height: V = B · h","One-Third Base Times Height: V = (1/3) B · h"],categories_ar:["مساحة القاعدة × الارتفاع: V = B · h","ثلث مساحة القاعدة × الارتفاع: V = (1/3) B · h"],items:[{s:"Right circular cylinder",s_ar:"أسطوانة دائرية قائمة",cat:0},{s:"Rectangular prism",s_ar:"منشور مستطيل القاعدة (متوازي مستطيلات)",cat:0},{s:"Right triangular prism",s_ar:"منشور ثلاثي قائم",cat:0},{s:"Right circular cone",s_ar:"مخروط دائري قائم",cat:1},{s:"Square-based pyramid",s_ar:"هرم رباعي منتظم",cat:1}],sol:"Prisms and cylinders use V = B · h; cones and pyramids taper to a point and use V = (1/3) B · h.",sol_ar:"المناشير والأسطوانات حجمها V = B · h؛ بينما المخاريط والأهرامات التي تلتقي في رأس مدبب حجمها V = (1/3) B · h."},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Area, Surface Area &amp; Volume)",q:"A student solves the equation \\(\\sqrt{2x + 16} = x - 4\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 16 = (x - 4)^2\\).","Expand the right-hand side: \\(2x + 16 = x^2 - 8x + 16\\).","Rearrange and factor: \\(x^2 - 10x = 0 \\implies x(x - 10) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 10\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{16} = -4\\) (\\(4 = -4\\)), which is false because the principal square root is non-negative (\\(x - 4 \\ge 0\\) requires \\(x \\ge 4\\)).","Expanding \\((x - 4)^2\\) should give \\(x^2 - 16\\) with no middle term.","Factoring \\(x^2 - 10x = 0\\) only yields \\(x = 10\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 16} = x - 4\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 4 \\ge 0 \\iff x \\ge 4\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 10\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Area, Surface Area &amp; Volume)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 16} = x - 4\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 16 = (x - 4)^2\\).","فك المربع الكامل: \\(2x + 16 = x^2 - 8x + 16\\).","الترتيب والتحليل: \\(x^2 - 10x = 0 \\implies x(x - 10) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 10\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(4 = -4\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 4\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 4 \\ge 0 \\implies x \\ge 4\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 10\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Area, Surface Area &amp; Volume)",q:"Let \\(f(x) = x^2 - 8x + 15\\) for \\(x \\ge 4\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 4)^2 - 16 + 15 = (x - 4)^2 + -1\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge -1\\) (or \\([-1, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 4)^2 + -1 \\implies (x - 4)^2 = y - -1\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 4\\)): \\(f^{-1}(x) = 4 + \\sqrt{x - -1}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge -1\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - -1}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 4\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Area, Surface Area &amp; Volume)",q_ar:"لتكن \\(f(x) = x^2 - 8x + 15\\) حيث \\(x \\ge 4\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(4 + \\sqrt{x - -1}\\) لأن \\(x \\ge 4\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Area, Surface Area &amp; Volume)",steps:[{l:"In \\(y = x^2 - 8x + 15\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"4",h:"Take half of 8."},{l:"Compute the minimum value \\(k = 15 - 4^2 =\\)",a:"-1",h:"Subtract 16 from 15."},{l:"Evaluate \\(y\\) when \\(x = 6\\): \\(y =\\)",a:"3",h:"Compute (2)^2 + -1."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Area, Surface Area &amp; Volume)",steps_ar:[{l:"في الدالة \\(y = x^2 - 8x + 15\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"4",h:"اقسم معامل x وهو 8 على 2."},{l:"احسب القيمة الصغرى \\(k = 15 - 4^2 =\\)",a:"-1",h:"اطرح 16 من 15."},{l:"احسب قيمة \\(y\\) عندما \\(x = 6\\):",a:"3",h:"احسب 4 + -1."}]},{t:"mt",ti:"Matching: Core Algebraic & Analytic Principles (Area, Surface Area &amp; Volume)",p:[{l:"\\(b^2 - 4ac = 0\\)",r:"Line is tangent to the quadratic curve (1 repeated root)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"Equals \\(\\text{ran}(f)\\) (Range of original function)"},{l:"\\(f(x - h) + k\\)",r:"Translation by vector \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"Vieta's root-coefficient relations"}],ti_ar:"مطابقة: المبادئ الجبرية والتحليلية الأساسية (Area, Surface Area &amp; Volume)",p_ar:[{l:"\\(b^2 - 4ac = 0\\)",r:"المستقيم مماس للمنحنى التربيعي (جذر حقيقي مكرر)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"يساوي مدى الدالة الأصلية \\(\\text{ran}(f)\\)"},{l:"\\(f(x - h) + k\\)",r:"إزاحة هندسية بالمتجه \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"علاقات فييت بين الجذور والمعاملات"}]}];D["geo-transform"]=[{t:"sr",ti:"Worked Example: Reflect a Point Over the y-axis",ti_ar:"مثال محلول: انعكاس نقطة حول محور الصادات",steps:["Reflect the point \\((3,-2)\\) over the y-axis. Reflecting over the y-axis negates the x-coordinate and keeps y the same: \\((x,y)\\to(-x,y)\\).","Apply to \\((3,-2)\\): \\((-3,-2)\\)."],steps_ar:["إجراء انعكاس للنقطة \\((3,-2)\\) حول محور الصادات (y). الانعكاس حول محور y يعكس إشارة الإحداثي السيني x ويبقي y كما هو: \\((x,y)\\to(-x,y)\\).","التطبيق على النقطة \\((3,-2)\\): ينتج \\((-3,-2)\\)."]},{t:"qc",ti:"Quick Check: Rotations",ti_ar:"فحص سريع: الدوران",q:"A 180° rotation about the origin maps \\((x,y)\\) to:",q_ar:"الدوران بزاوية 180° حول نقطة الأصل ينقل النقطة \\((x,y)\\) إلى:",o:["\\((-x,-y)\\)","\\((x,-y)\\)","\\((-x,y)\\)","\\((y,x)\\)"],o_ar:["\\((-x,-y)\\)","\\((x,-y)\\)","\\((-x,y)\\)","\\((y,x)\\)"],a:0,ex:"A 180° rotation about the origin negates both coordinates.",ex_ar:"الدوران بزاوية 180° حول نقطة الأصل يعكس إشارتي كلا الإحداثيين."},{t:"cat",ti:"Categorize: Rigid vs Non-Rigid Motions",ti_ar:"تصنيف: تحويلات التطابق (الصلبة) مقابل التحويلات غير الصلبة",categories:["Isometry (Rigid Motion)","Non-Rigid Motion"],categories_ar:["تحويل تطابق (صلب - يحافظ على الأبعاد)","تحويل غير صلب (يغير الأبعاد)"],items:[{s:"Translation by vector ⟨-2, 5⟩",s_ar:"إزاحة بالمتجه ⟨-2, 5⟩",cat:0},{s:"Reflection across the line y = -x",s_ar:"انعكاس حول المستقيم y = -x",cat:0},{s:"Rotation of 90° about origin",s_ar:"دوران بزاوية 90° حول نقطة الأصل",cat:0},{s:"Dilation by scale factor k = 2.5",s_ar:"تمدد بمعامل قياس k = 2.5",cat:1},{s:"Horizontal stretch by factor 3",s_ar:"تمدد أفقي بمعامل 3",cat:1}],sol:"Translations, reflections, and rotations preserve distance and angle measure (isometries); dilations and stretches change size or shape.",sol_ar:"الإزاحات والانعكاسات والدورانات تحافظ على الأبعاد والزوايا (تحويلات تطابق)؛ بينما التمدد يغير الحجم أو الشكل."},{t:"num",ti:"Dilation Coordinate Value",ti_ar:"إحداثي نقطة بعد التمدد",q:"The point (4, -6) is dilated with center at the origin by a scale factor of \\(k = 0.5\\). What is the resulting x-coordinate?",q_ar:"أجري تمدد للنقطة (4, -6) مركزه نقطة الأصل ومعامله \\(k = 0.5\\). ما الإحداثي السيني x الناتج؟",a:2,tol:.001,h:"Multiply the x-coordinate by 0.5.",h_ar:"اضرب الإحداثي السيني في 0.5.",sol:"4 * 0.5 = 2.",sol_ar:"4 * 0.5 = 2."},{t:"ord",ti:"Order the Steps: Composition of Geometric Transformations",ti_ar:"رتّب الخطوات: تركيب التحويلات الهندسية",q:"Arrange the steps to reflect point A(-2, 4) across line y = x, then translate by vector ⟨3, -1⟩:",q_ar:"رتب خطوات إجراء انعكاس للنقطة A(-2, 4) حول المستقيم y = x، ثم إزاحتها بالمتجه ⟨3, -1⟩:",items:["Recall rule for reflection across line y = x: swap coordinates (x, y) ⟶ (y, x)","Apply reflection to A(-2, 4): A'(4, -2)","Recall rule for translation by ⟨h, k⟩: (x, y) ⟶ (x + h, y + k)","Apply translation ⟨3, -1⟩ to A'(4, -2): (4 + 3, -2 - 1)","State the final transformed coordinates: A''(7, -3)"],items_ar:["تذكر قاعدة الانعكاس حول المستقيم y = x: تبديل الإحداثيين (x, y) ⟶ (y, x)","تطبيق الانعكاس على النقطة A(-2, 4): A'(4, -2)","تذكر قاعدة الإزاحة بالمتجه ⟨h, k⟩: (x, y) ⟶ (x + h, y + k)","تطبيق الإزاحة بالمتجه ⟨3, -1⟩ على A'(4, -2): (4 + 3, -2 - 1)","تحديد الإحداثيات النهائية الناتجة: A''(7, -3)"],sol:"Perform composite transformations in sequence, applying the coordinates rule step by step.",sol_ar:"نفذ التحويلات المركبة بالترتيب، بتطبيق قواعد الإحداثيات خطوة بخطوة."},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Transformations &amp; Symmetry)",q:"A student solves the equation \\(\\sqrt{2x + 4} = x - 2\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 4 = (x - 2)^2\\).","Expand the right-hand side: \\(2x + 4 = x^2 - 4x + 4\\).","Rearrange and factor: \\(x^2 - 6x = 0 \\implies x(x - 6) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 6\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{4} = -2\\) (\\(2 = -2\\)), which is false because the principal square root is non-negative (\\(x - 2 \\ge 0\\) requires \\(x \\ge 2\\)).","Expanding \\((x - 2)^2\\) should give \\(x^2 - 4\\) with no middle term.","Factoring \\(x^2 - 6x = 0\\) only yields \\(x = 6\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 4} = x - 2\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 2 \\ge 0 \\iff x \\ge 2\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 6\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Transformations &amp; Symmetry)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 4} = x - 2\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 4 = (x - 2)^2\\).","فك المربع الكامل: \\(2x + 4 = x^2 - 4x + 4\\).","الترتيب والتحليل: \\(x^2 - 6x = 0 \\implies x(x - 6) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 6\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(2 = -2\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 2\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 2 \\ge 0 \\implies x \\ge 2\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 6\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Transformations &amp; Symmetry)",q:"Let \\(f(x) = x^2 - 4x + 3\\) for \\(x \\ge 2\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 2)^2 - 4 + 3 = (x - 2)^2 + -1\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge -1\\) (or \\([-1, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 2)^2 + -1 \\implies (x - 2)^2 = y - -1\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 2\\)): \\(f^{-1}(x) = 2 + \\sqrt{x - -1}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge -1\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - -1}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 2\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Transformations &amp; Symmetry)",q_ar:"لتكن \\(f(x) = x^2 - 4x + 3\\) حيث \\(x \\ge 2\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(2 + \\sqrt{x - -1}\\) لأن \\(x \\ge 2\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Transformations &amp; Symmetry)",steps:[{l:"In \\(y = x^2 - 4x + 3\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"2",h:"Take half of 4."},{l:"Compute the minimum value \\(k = 3 - 2^2 =\\)",a:"-1",h:"Subtract 4 from 3."},{l:"Evaluate \\(y\\) when \\(x = 4\\): \\(y =\\)",a:"3",h:"Compute (2)^2 + -1."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Transformations &amp; Symmetry)",steps_ar:[{l:"في الدالة \\(y = x^2 - 4x + 3\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"2",h:"اقسم معامل x وهو 4 على 2."},{l:"احسب القيمة الصغرى \\(k = 3 - 2^2 =\\)",a:"-1",h:"اطرح 4 من 3."},{l:"احسب قيمة \\(y\\) عندما \\(x = 4\\):",a:"3",h:"احسب 4 + -1."}]},{t:"mt",ti:"Matching: Core Algebraic & Analytic Principles (Transformations &amp; Symmetry)",p:[{l:"\\(b^2 - 4ac = 0\\)",r:"Line is tangent to the quadratic curve (1 repeated root)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"Equals \\(\\text{ran}(f)\\) (Range of original function)"},{l:"\\(f(x - h) + k\\)",r:"Translation by vector \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"Vieta's root-coefficient relations"}],ti_ar:"مطابقة: المبادئ الجبرية والتحليلية الأساسية (Transformations &amp; Symmetry)",p_ar:[{l:"\\(b^2 - 4ac = 0\\)",r:"المستقيم مماس للمنحنى التربيعي (جذر حقيقي مكرر)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"يساوي مدى الدالة الأصلية \\(\\text{ran}(f)\\)"},{l:"\\(f(x - h) + k\\)",r:"إزاحة هندسية بالمتجه \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"علاقات فييت بين الجذور والمعاملات"}]}];D["geo-coord"]=[{t:"fn",ti:"Explorer: Line Slope \\(y=mx+2\\)",ti_ar:"مستكشف: ميل الخط المستقيم \\(y=mx+2\\)",fns:[{expr:"m*x+2",color:"#1E3A6E",label:"y=mx+2"}],xrange:[-5,5],yrange:[-5,10],params:[{name:"m",label:"Slope m",min:-3,max:3,step:.5,default:1}]},{t:"sr",ti:"Worked Example: Distance Between Two Points",ti_ar:"مثال محلول: المسافة بين نقطتين",steps:["Find the distance between \\((1,2)\\) and \\((4,6)\\). Use the distance formula: \\(d=\\sqrt{(x_2-x_1)^2+(y_2-y_1)^2}\\).","Substitute: \\(d=\\sqrt{(4-1)^2+(6-2)^2}=\\sqrt{9+16}\\).","Simplify: \\(d=\\sqrt{25}=5\\)."],steps_ar:["أوجد المسافة بين النقطتين \\((1,2)\\) و \\((4,6)\\). استخدام قانون المسافة: \\(d=\\sqrt{(x_2-x_1)^2+(y_2-y_1)^2}\\).","التعويض: \\(d=\\sqrt{(4-1)^2+(6-2)^2}=\\sqrt{9+16}\\).","التبسيط: \\(d=\\sqrt{25}=5\\)."]},{t:"qc",ti:"Quick Check: Midpoint",ti_ar:"فحص سريع: نقطة المنتصف",q:"The midpoint of \\((2,4)\\) and \\((8,10)\\) is:",q_ar:"نقطة منتصف القطعة المستقيمة الواصلة بين \\((2,4)\\) و \\((8,10)\\) هي:",o:["\\((5,7)\\)","\\((6,7)\\)","\\((5,6)\\)","\\((10,14)\\)"],o_ar:["\\((5,7)\\)","\\((6,7)\\)","\\((5,6)\\)","\\((10,14)\\)"],a:0,ex:"Midpoint = average of coordinates: \\(\\left(\\frac{2+8}{2},\\frac{4+10}{2}\\right)=(5,7)\\).",ex_ar:"نقطة المنتصف = متوسط الإحداثيات: \\(\\left(\\frac{2+8}{2},\\frac{4+10}{2}\\right)=(5,7)\\)."},{t:"num",ti:"Perpendicular Slope Calculation",ti_ar:"حساب ميل المستقيم العمودي",q:"Line \\(L_1\\) has equation \\(2x + 8y = 12\\). What is the slope of a line \\(L_2\\) perpendicular to \\(L_1\\)?",q_ar:"المستقيم \\(L_1\\) معادلته \\(2x + 8y = 12\\). ما ميل المستقيم \\(L_2\\) العمودي على \\(L_1\\)؟",a:4,tol:.001,h:"Slope of L1 is -2/8 = -1/4. Perpendicular slope is negative reciprocal: -(-4) = 4.",h_ar:"ميل L1 هو -2/8 = -1/4. ميل العمودي هو مقلوب المعكوس الجمعي: -(-4) = 4.",sol:"4.",sol_ar:"4."},{t:"ord",ti:"Order the Steps: Equation of a Perpendicular Bisector",ti_ar:"رتّب الخطوات: معادلة المنصف العمودي لقطعة مستقيمة",q:"Arrange the steps to find the perpendicular bisector of segment AB connecting A(2, -1) and B(6, 7):",q_ar:"رتب خطوات إيجاد معادلة المنصف العمودي للقطعة AB الواصلة بين A(2, -1) و B(6, 7):",items:["Find the midpoint M: M = ((2+6)/2, (-1+7)/2) = (4, 3)","Find the slope of segment AB: m_AB = (7 - (-1)) / (6 - 2) = 8 / 4 = 2","Find perpendicular slope: m_perp = -1 / 2","Write point-slope equation through M(4, 3): y - 3 = (-1/2)(x - 4)","Simplify to slope-intercept form: y = (-1/2)x + 5"],items_ar:["إيجاد نقطة المنتصف M: M = ((2+6)/2, (-1+7)/2) = (4, 3)","إيجاد ميل القطعة المستقيمة AB: m_AB = (7 - (-1)) / (6 - 2) = 8 / 4 = 2","إيجاد ميل العمودي: m_perp = -1 / 2","كتابة معادلة المستقيم بصيغة الميل ونقطة عبر M(4, 3): y - 3 = (-1/2)(x - 4)","التبسيط إلى صيغة الميل والمقطع: y = (-1/2)x + 5"],sol:"The perpendicular bisector passes through the midpoint with a slope perpendicular to the segment.",sol_ar:"المنصف العمودي يمر بنقطة المنتصف ويكون ميله عمودياً على ميل القطعة الأصلية."},{t:"cat",ti:"Classify Lines by Slope Relationships",ti_ar:"تصنيف المستقيمات حسب علاقة الميول",categories:["Parallel Lines (Equal Slopes: m₁ = m₂)","Perpendicular Lines (Negative Reciprocals: m₁ · m₂ = -1)"],categories_ar:["مستقيمان متوازيان (الميلان متساويان: m₁ = m₂)","مستقيمان متعامدان (حاصل ضرب الميلين = -1)"],items:[{s:"y = 3x + 1 and y = 3x - 5",s_ar:"y = 3x + 1 و y = 3x - 5",cat:0},{s:"y = -0.5x + 4 and y = -0.5x - 2",s_ar:"y = -0.5x + 4 و y = -0.5x - 2",cat:0},{s:"y = 2x + 3 and y = -0.5x + 1",s_ar:"y = 2x + 3 و y = -0.5x + 1",cat:1},{s:"y = (3/4)x - 2 and y = (-4/3)x + 7",s_ar:"y = (3/4)x - 2 و y = (-4/3)x + 7",cat:1}],sol:"Parallel lines have matching slopes; perpendicular lines have negative reciprocal slopes whose product is -1.",sol_ar:"المستقيمات المتوازية لها ميول متطابقة؛ بينما المستقيمات المتعامدة حاصل ضرب ميولها يساوي -1."},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Coordinate Geometry)",q:"A student solves the equation \\(\\sqrt{2x + 9} = x - 3\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 9 = (x - 3)^2\\).","Expand the right-hand side: \\(2x + 9 = x^2 - 6x + 9\\).","Rearrange and factor: \\(x^2 - 8x = 0 \\implies x(x - 8) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 8\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{9} = -3\\) (\\(3 = -3\\)), which is false because the principal square root is non-negative (\\(x - 3 \\ge 0\\) requires \\(x \\ge 3\\)).","Expanding \\((x - 3)^2\\) should give \\(x^2 - 9\\) with no middle term.","Factoring \\(x^2 - 8x = 0\\) only yields \\(x = 8\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 9} = x - 3\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 3 \\ge 0 \\iff x \\ge 3\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 8\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Coordinate Geometry)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 9} = x - 3\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 9 = (x - 3)^2\\).","فك المربع الكامل: \\(2x + 9 = x^2 - 6x + 9\\).","الترتيب والتحليل: \\(x^2 - 8x = 0 \\implies x(x - 8) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 8\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(3 = -3\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 3\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 3 \\ge 0 \\implies x \\ge 3\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 8\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Coordinate Geometry)",q:"Let \\(f(x) = x^2 - 6x + 13\\) for \\(x \\ge 3\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 3)^2 - 9 + 13 = (x - 3)^2 + 4\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge 4\\) (or \\([4, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 3)^2 + 4 \\implies (x - 3)^2 = y - 4\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 3\\)): \\(f^{-1}(x) = 3 + \\sqrt{x - 4}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge 4\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - 4}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 3\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Coordinate Geometry)",q_ar:"لتكن \\(f(x) = x^2 - 6x + 13\\) حيث \\(x \\ge 3\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(3 + \\sqrt{x - 4}\\) لأن \\(x \\ge 3\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Coordinate Geometry)",steps:[{l:"In \\(y = x^2 - 6x + 13\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"3",h:"Take half of 6."},{l:"Compute the minimum value \\(k = 13 - 3^2 =\\)",a:"4",h:"Subtract 9 from 13."},{l:"Evaluate \\(y\\) when \\(x = 5\\): \\(y =\\)",a:"8",h:"Compute \\((2)^2 + 4\\)."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Coordinate Geometry)",steps_ar:[{l:"في الدالة \\(y = x^2 - 6x + 13\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"3",h:"اقسم معامل x وهو 6 على 2."},{l:"احسب القيمة الصغرى \\(k = 13 - 3^2 =\\)",a:"4",h:"اطرح 9 من 13."},{l:"احسب قيمة \\(y\\) عندما \\(x = 5\\):",a:"8",h:"احسب \\(4 + 4\\)."}]},{t:"mt",ti:"Matching: Core Algebraic & Analytic Principles (Coordinate Geometry)",p:[{l:"\\(b^2 - 4ac = 0\\)",r:"Line is tangent to the quadratic curve (1 repeated root)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"Equals \\(\\text{ran}(f)\\) (Range of original function)"},{l:"\\(f(x - h) + k\\)",r:"Translation by vector \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"Vieta's root-coefficient relations"}],ti_ar:"مطابقة: المبادئ الجبرية والتحليلية الأساسية (Coordinate Geometry)",p_ar:[{l:"\\(b^2 - 4ac = 0\\)",r:"المستقيم مماس للمنحنى التربيعي (جذر حقيقي مكرر)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"يساوي مدى الدالة الأصلية \\(\\text{ran}(f)\\)"},{l:"\\(f(x - h) + k\\)",r:"إزاحة هندسية بالمتجه \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"علاقات فييت بين الجذور والمعاملات"}]}];D["geo-prob"]=[{t:"sr",ti:"Worked Example: Geometric Probability",ti_ar:"مثال محلول: الاحتمال الهندسي",steps:["A square dartboard has side \\(10\\) with a circular target of radius \\(3\\) at its center. Area of the square: \\(10\\times10=100\\).","Area of the circle: \\(\\pi r^2=\\pi(3)^2=9\\pi\\).","Probability \\(=\\dfrac{\\text{circle area}}{\\text{square area}}=\\dfrac{9\\pi}{100}\\approx0.283\\)."],steps_ar:["لوحة سهام مربعة طول ضلعها \\(10\\) وفي مركزها هدف دائري نصف قطره \\(3\\). مساحة المربع: \\(10\\times10=100\\).","مساحة الدائرة: \\(\\pi r^2=\\pi(3)^2=9\\pi\\).","الاحتمال \\(=\\dfrac{\\text{مساحة الدائرة}}{\\text{مساحة المربع}}=\\dfrac{9\\pi}{100}\\approx0.283\\)."]},{t:"qc",ti:"Quick Check: Coin Flips",ti_ar:"فحص سريع: إلقاء قطعة النقود",q:"A coin is flipped 3 times. What is \\(P(\\text{exactly 2 heads})\\)?",q_ar:"ألقيت قطعة نقود 3 مرات. ما قيمة \\(P(\\text{ظهور شعارين تماماً})\\)؟",o:["\\(\\dfrac38\\)","\\(\\dfrac12\\)","\\(\\dfrac14\\)","\\(\\dfrac18\\)"],o_ar:["\\(\\dfrac38\\)","\\(\\dfrac12\\)","\\(\\dfrac14\\)","\\(\\dfrac18\\)"],a:0,ex:"There are \\(\\binom32=3\\) ways to get 2 heads out of 8 equally likely outcomes: \\(\\dfrac38\\).",ex_ar:"توجد \\(\\binom32=3\\) طرق للحصول على شعارين من بين 8 نواتج متساوية الإمكانية: \\(\\dfrac38\\)."},{t:"num",ti:"Geometric Probability on Line Segment",ti_ar:"الاحتمال الهندسي على قطعة مستقيمة",q:"A point is chosen at random on a line segment of length 20. What is the probability (as a decimal) that it lands on a subsegment of length 7?",q_ar:"اختيرت نقطة عشوائياً على قطعة مستقيمة طولها 20. ما احتمال (في صورة كسر عشري) أن تقع النقطة على قطعة جزئية طولها 7؟",a:.35,tol:.001,h:"Divide subsegment length by total length: 7 / 20.",h_ar:"اقسم طول القطعة الجزئية على الطول الكلي: 7 / 20.",sol:"7 / 20 = 0.35.",sol_ar:"7 / 20 = 0.35."},{t:"ord",ti:"Order the Steps: Geometric Probability in Concentric Target",ti_ar:"رتّب الخطوات: الاحتمال الهندسي في هدف ذي دوائر متحدة المركز",q:"Arrange the steps to find probability that a randomly landing dart hits the middle ring (radius 10 to 20 cm) on a target of radius 30 cm:",q_ar:"رتب خطوات إيجاد احتمال استقرار سهم عشوائي في الحلقة الوسطى (نصف القطر من 10 إلى 20 سم) على هدف نصف قطره 30 سم:",items:["Find total target area: Area_total = π (30²) = 900π cm²","Find area of outer circle of middle ring: π (20²) = 400π cm²","Find area of inner circle: π (10²) = 100π cm²","Calculate middle ring area: Area_ring = 400π - 100π = 300π cm²","Divide to find probability: P = 300π / 900π = 1/3 ≈ 0.333"],items_ar:["حساب مساحة الهدف الكلية: المساحة الكلية = π (30²) = 900π سم²","حساب مساحة الدائرة الخارجية للحلقة الوسطى: π (20²) = 400π سم²","حساب مساحة الدائرة الداخلية: π (10²) = 100π سم²","حساب مساحة الحلقة الوسطى: مساحة الحلقة = 400π - 100π = 300π سم²","القسمة لحساب الاحتمال: P = 300π / 900π = 1/3 ≈ 0.333"],sol:"Geometric probability equals the favorable target area divided by the total possible region area.",sol_ar:"الاحتمال الهندسي يساوي مساحة المنطقة المستهدفة مقسومة على مساحة المنطقة الكلية الممكنة."},{t:"cat",ti:"Classify Probability Events by Nature",ti_ar:"تصنيف أحداث الاحتمالات حسب طبيعتها",categories:["Geometric / Continuous Probability","Classical / Discrete Probability"],categories_ar:["احتمال هندسي / متصل","احتمال كلاسيكي / منفصل"],items:[{s:"Probability a dart lands in a circular target on a square board",s_ar:"احتمال استقرار سهم في هدف دائري على لوحة مربعة",cat:0},{s:"Probability a random waiting time is under 5 minutes",s_ar:"احتمال أن يقل وقت الانتظار العشوائي عن 5 دقائق",cat:0},{s:"Probability a randomly selected point on [0, 10] lies in [2, 6]",s_ar:"احتمال وقوع نقطة عشوائية على الفترة [0, 10] في الفترة [2, 6]",cat:0},{s:"Probability of rolling a sum of 7 on two standard six-sided dice",s_ar:"احتمال الحصول على مجموع 7 عند رمي حجري نرد سداسيين",cat:1},{s:"Probability of drawing an Ace from a standard 52-card deck",s_ar:"احتمال سحب بطاقة الآس من مجموعة أوراق لعب قياسية (52 بطاقة)",cat:1}],sol:"Continuous/geometric probability relies on ratios of lengths, areas, or volumes; discrete probability relies on counting outcomes.",sol_ar:"الاحتمال المتصل أو الهندسي يعتمد على نسب الأطوال والمساحات والحجوم؛ بينما الاحتمال المنفصل يعتمد على عد النواتج الممكنة."},{t:"se",ti:"Spot the Error: Algebraic & Domain Verification (Probability)",q:"A student solves the equation \\(\\sqrt{2x + 4} = x - 2\\) step by step. Which step introduces an invalid conclusion?",steps:["Square both sides to eliminate the radical: \\(2x + 4 = (x - 2)^2\\).","Expand the right-hand side: \\(2x + 4 = x^2 - 4x + 4\\).","Rearrange and factor: \\(x^2 - 6x = 0 \\implies x(x - 6) = 0\\).","Conclude that both \\(x = 0\\) and \\(x = 6\\) are valid real solutions."],errorStep:4,reasons:["Substituting \\(x = 0\\) into the original equation gives \\(\\sqrt{4} = -2\\) (\\(2 = -2\\)), which is false because the principal square root is non-negative (\\(x - 2 \\ge 0\\) requires \\(x \\ge 2\\)).","Expanding \\((x - 2)^2\\) should give \\(x^2 - 4\\) with no middle term.","Factoring \\(x^2 - 6x = 0\\) only yields \\(x = 6\\)."],correctReason:0,h:"Test \\(x = 0\\) in the original equation \\(\\sqrt{2x + 4} = x - 2\\).",sol:"Squaring both sides is a non-reversible step unless \\(x - 2 \\ge 0 \\iff x \\ge 2\\). Therefore \\(x = 0\\) is an extraneous root and \\(x = 6\\) is the unique solution.",ti_ar:"اكتشف الخطأ: الجذور الدخيلة والتحقق من المجال (Probability)",q_ar:"يحل طالب المعادلة \\(\\sqrt{2x + 4} = x - 2\\) خطوة بخطوة. أي خطوة تتضمن استنتاجاً خاطئاً؟",steps_ar:["تربيع الطرفين للتخلص من الجذر: \\(2x + 4 = (x - 2)^2\\).","فك المربع الكامل: \\(2x + 4 = x^2 - 4x + 4\\).","الترتيب والتحليل: \\(x^2 - 6x = 0 \\implies x(x - 6) = 0\\).","استنتاج أن كلاً من \\(x = 0\\) و \\(x = 6\\) حلان صحيحان للمعادلة الأصلية."],reasons_ar:["التعويض عن \\(x = 0\\) في المعادلة الأصلية يعطي \\(2 = -2\\) وهو مستحيل لأن الجذر التربيعي الأساسي غير سالب (يجب أن يتحقق \\(x \\ge 2\\)).","فك التربيع غير صحيح.","التحليل بإخراج العامل المشترك غير صحيح."],h_ar:"عوّض عن \\(x = 0\\) في المعادلة الأصلية للتحقق من إشارة الطرف الأيمن.",sol_ar:"الشرط اللازم هو \\(x - 2 \\ge 0 \\implies x \\ge 2\\)، لذا يُرفض الجذر الدخيل \\(x = 0\\) ويبقى \\(x = 6\\) فقط."},{t:"ms",ti:"Examiner Mode: Multi-Step Structured Problem (Probability)",q:"Let \\(f(x) = x^2 - 4x + 8\\) for \\(x \\ge 2\\). (a) Express \\(f(x)\\) in completed-square vertex form and state the range of \\(f\\). (b) Find an expression for the inverse function \\(f^{-1}(x)\\) and state its domain.",parts:[{label:"Part (a) — Vertex Form & Range",marks:2,rubric:[{code:"M1",marks:1,text:"Complete the square: \\(f(x) = (x - 2)^2 - 4 + 8 = (x - 2)^2 + 4\\)."},{code:"A1",marks:1,text:"State exact range: \\(f(x) \\ge 4\\) (or \\([4, \\infty)\\))."}]},{label:"Part (b) — Inverse Function & Domain",marks:3,rubric:[{code:"M1",marks:1,text:"Set \\(y = (x - 2)^2 + 4 \\implies (x - 2)^2 = y - 4\\)."},{code:"A1",marks:1,text:"Select positive branch (since \\(x \\ge 2\\)): \\(f^{-1}(x) = 2 + \\sqrt{x - 4}\\)."},{code:"B1",marks:1,text:"State domain of \\(f^{-1}\\): \\(x \\ge 4\\) (matching the range of \\(f\\))."}]}],examinerTip:"Writing \\(\\pm\\sqrt{x - 4}\\) for \\(f^{-1}(x)\\) loses the final A1 mark because a function must be single-valued; use the domain restriction \\(x \\ge 2\\) to choose the \\(+\\) sign.",ti_ar:"وضع المصحح: إكمال المربع والدالة العكسية (Probability)",q_ar:"لتكن \\(f(x) = x^2 - 4x + 8\\) حيث \\(x \\ge 2\\). (أ) اكتب \\(f(x)\\) في صورة المربع الكامل وحدد مداها. (ب) أوجد قاعدة الدالة العكسية \\(f^{-1}(x)\\) ومجالها.",examinerTip_ar:"الدالة العكسية يجب أن تكون وحيدة القيمة، لذا نختار الإشارة الموجبة للجذر \\(2 + \\sqrt{x - 4}\\) لأن \\(x \\ge 2\\)."},{t:"sb",ti:"Step Builder: Completing the Square & Vertex Analysis (Probability)",steps:[{l:"In \\(y = x^2 - 4x + 8\\), halve the \\(x\\)-coefficient to write \\((x - h)^2\\) where \\(h =\\)",a:"2",h:"Take half of 4."},{l:"Compute the minimum value \\(k = 8 - 2^2 =\\)",a:"4",h:"Subtract 4 from 8."},{l:"Evaluate \\(y\\) when \\(x = 4\\): \\(y =\\)",a:"8",h:"Compute \\((2)^2 + 4\\)."}],ti_ar:"بناء الخطوات: إكمال المربع وإيجاد القيمة الصغرى (Probability)",steps_ar:[{l:"في الدالة \\(y = x^2 - 4x + 8\\): قيمة \\(h\\) في \\((x - h)^2\\) تساوي:",a:"2",h:"اقسم معامل x وهو 4 على 2."},{l:"احسب القيمة الصغرى \\(k = 8 - 2^2 =\\)",a:"4",h:"اطرح 4 من 8."},{l:"احسب قيمة \\(y\\) عندما \\(x = 4\\):",a:"8",h:"احسب \\(4 + 4\\)."}]},{t:"mt",ti:"Matching: Core Algebraic & Analytic Principles (Probability)",p:[{l:"\\(b^2 - 4ac = 0\\)",r:"Line is tangent to the quadratic curve (1 repeated root)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"Equals \\(\\text{ran}(f)\\) (Range of original function)"},{l:"\\(f(x - h) + k\\)",r:"Translation by vector \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"Vieta's root-coefficient relations"}],ti_ar:"مطابقة: المبادئ الجبرية والتحليلية الأساسية (Probability)",p_ar:[{l:"\\(b^2 - 4ac = 0\\)",r:"المستقيم مماس للمنحنى التربيعي (جذر حقيقي مكرر)"},{l:"\\(\\text{dom}(f^{-1})\\)",r:"يساوي مدى الدالة الأصلية \\(\\text{ran}(f)\\)"},{l:"\\(f(x - h) + k\\)",r:"إزاحة هندسية بالمتجه \\(\\binom{h}{k}\\)"},{l:"\\(x_1 + x_2 = -b/a,\\; x_1 x_2 = c/a\\)",r:"علاقات فييت بين الجذور والمعاملات"}]}]});